# -*- coding: utf-8 -*-
import json
import os
import sys
import threading
import time

try:
    from urllib.request import Request, urlopen
except ImportError:  # pragma: no cover - Kodi/Python 2 compatibility
    from urllib2 import Request, urlopen

import xbmc
import xbmcaddon
import xbmcgui


ADDON_ID = 'plugin.video.elementum'
ADDON = xbmcaddon.Addon(ADDON_ID)
ADDON_PATH = ADDON.getAddonInfo('path')
BRIDGE_BASE = 'http://127.0.0.1:65222'
POLL_INTERVAL = 0.35

ACTION_PARENT_DIR = 9
ACTION_PREVIOUS_MENU = 10
KEY_NAV_BACK = 92
ACTION_NAV_BACK = 110


def log(message, level=xbmc.LOGWARNING):
    xbmc.log('[plugin.video.elementum] %s' % message, level)


def request_json(path, method='GET', body=None, timeout=3):
    data = None
    headers = {'Cache-Control': 'no-store'}
    if body is not None:
        data = json.dumps(body).encode('utf-8')
        headers['Content-Type'] = 'application/json; charset=utf-8'

    request = Request(BRIDGE_BASE + path, data=data, headers=headers)
    if hasattr(request, 'method'):
        request.method = method
    elif method != 'GET':
        request.get_method = lambda: method

    response = urlopen(request, timeout=timeout)
    payload = response.read()
    if not payload:
        return {}
    if not isinstance(payload, str):
        payload = payload.decode('utf-8')
    return json.loads(payload)


def wait_for_state(session_id, monitor):
    deadline = time.time() + 15.0
    while not monitor.abortRequested() and time.time() < deadline:
        try:
            state = request_json('/state')
            if (
                state.get('active')
                and state.get('mode') == 'kodi'
                and state.get('session') == session_id
            ):
                return state
        except Exception as exc:
            log(
                'Progressive Kodi runner waiting for state: session=%s error=%s'
                % (session_id, repr(exc))
            )
        monitor.waitForAbort(0.2)
    return None


def finish_session(session_id, choice):
    path = '/select' if choice >= 0 else '/cancel'
    try:
        request_json(
            path,
            method='POST',
            body={'session': session_id, 'choice': int(choice)},
        )
        log(
            'Progressive Kodi runner returned choice: session=%s choice=%d'
            % (session_id, choice)
        )
    except Exception as exc:
        log(
            'Progressive Kodi runner failed to return choice: session=%s error=%s'
            % (session_id, repr(exc)),
            xbmc.LOGERROR,
        )


class ProgressiveKodiDialog(xbmcgui.WindowXMLDialog):
    def __init__(self, *args, **kwargs):
        self.title = kwargs.get('title') or 'Elementum'
        self.items = list(kwargs.get('items') or [])
        self.lock = threading.RLock()
        self.initialized = False
        self.finished = False
        self.retval = -1
        self.value = ''
        self.count = 0

    def onInit(self):
        try:
            with self.lock:
                self.initialized = True
                self.getControl(32501).setLabel(self.title)
                self._render_locked('onInit')
                self.setFocusId(32503)
        except Exception as exc:
            log('Progressive Kodi dialog onInit failed: %s' % repr(exc), xbmc.LOGERROR)
            raise

    def updateItems(self, items):
        with self.lock:
            self.items = list(items)
            if not self.initialized or self.finished:
                return
            self._render_locked('update')

    def _render_locked(self, source):
        control = self.getControl(32503)
        selected = control.getSelectedPosition()
        control.reset()
        self.count = 0

        for raw_item in self.items:
            labels = raw_item.split('\n')
            label1 = labels[0]
            label2 = labels[1] if len(labels) > 1 else ''
            icon = labels[2] if len(labels) > 2 else None
            multi = len(labels) > 3 and labels[3] == 'multi'

            item = xbmcgui.ListItem(label=label1, label2=label2)
            item.setProperty('index', str(self.count))
            item.setProperty('value', raw_item)

            if multi:
                item.setArt({
                    'icon': os.path.join(
                        ADDON_PATH,
                        'resources',
                        'img',
                        'multi-cloud.png',
                    )
                })
            elif icon:
                item.setArt({'icon': icon})
            else:
                item.setArt({
                    'icon': os.path.join(
                        ADDON_PATH,
                        'resources',
                        'img',
                        'cloud.png',
                    )
                })

            control.addItem(item)
            self.count += 1

        if self.count:
            control.selectItem(min(max(selected, 0), self.count - 1))

        log(
            'Progressive Kodi dialog %s complete: items=%d control_size=%d'
            % (source, self.count, control.size())
        )

    def onClick(self, control_id):
        if control_id == 32500:
            self.close()
            return

        if control_id == 32503:
            with self.lock:
                selected = self.getControl(32503).getSelectedItem()
                if selected is not None:
                    try:
                        self.retval = int(selected.getProperty('index'))
                    except Exception:
                        self.retval = -1
                    self.value = selected.getProperty('value') or ''
            self.close()

    def onAction(self, action):
        if action.getId() in (
            ACTION_PARENT_DIR,
            ACTION_PREVIOUS_MENU,
            KEY_NAV_BACK,
            ACTION_NAV_BACK,
        ):
            self.close()

    def close(self):
        with self.lock:
            self.finished = True
        return super(ProgressiveKodiDialog, self).close()


def run(session_id):
    monitor = xbmc.Monitor()
    state = wait_for_state(session_id, monitor)
    if state is None:
        log(
            'Progressive Kodi runner did not receive state: session=%s'
            % session_id,
            xbmc.LOGERROR,
        )
        return

    try:
        kodi_major = int((xbmc.getInfoLabel('System.BuildVersion') or '17').split('.')[0])
    except Exception:
        kodi_major = 17

    xml_name = (
        'DialogSelectLargeLegacy.xml'
        if kodi_major <= 16
        else 'DialogSelectLarge.xml'
    )

    window = ProgressiveKodiDialog(
        xml_name,
        ADDON_PATH,
        'Default',
        title=state.get('title') or 'Elementum',
        items=state.get('items') or [],
    )

    stop_event = threading.Event()
    last_update = [state.get('updated_at')]

    def poll_updates():
        while not stop_event.is_set() and not monitor.abortRequested():
            try:
                latest = request_json('/state')
                if not latest.get('active'):
                    window.close()
                    return
                if latest.get('session') != session_id:
                    window.close()
                    return
                if latest.get('done'):
                    window.close()
                    return

                updated_at = latest.get('updated_at')
                if updated_at != last_update[0]:
                    last_update[0] = updated_at
                    window.updateItems(latest.get('items') or [])
            except Exception as exc:
                log(
                    'Progressive Kodi runner poll failed: session=%s error=%s'
                    % (session_id, repr(exc))
                )

            stop_event.wait(POLL_INTERVAL)

    poller = threading.Thread(
        target=poll_updates,
        name='elementum-progressive-kodi-poller',
    )
    poller.daemon = True
    poller.start()

    log(
        'Progressive Kodi dialog opening: session=%s items=%d'
        % (session_id, len(state.get('items') or []))
    )

    try:
        window.doModal()
    finally:
        stop_event.set()
        poller.join(2.0)

    choice = int(getattr(window, 'retval', -1))
    finish_session(session_id, choice)
    del window


if __name__ == '__main__':
    if len(sys.argv) < 2 or not sys.argv[1]:
        log('Progressive Kodi runner started without session ID', xbmc.LOGERROR)
    else:
        run(sys.argv[1])
